180→// resolveAgentAndTranscript resolves the agent and transcript path, with auto-detection fallback.
181→func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName) (agent.Agent, string, error) {
182→	ag, err := agent.Get(agentName)
183→	if err != nil {
184→		return nil, "", fmt.Errorf("agent %q not available: %w", agentName, err)
185→	}
186→
187→	transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
188→	if err != nil {
189→		detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
190→		if detectErr != nil {
191→			return nil, "", err
192→		}
193→		ag = detectedAg
194→		transcriptPath = detectedPath
195→		logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
196→		fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
197→	}
198→
199→	return ag, transcriptPath, nil
200→}
