202→// collectFileChanges gathers modified, new, and deleted files from both transcript analysis and git status.
203→// Returns detectionFailed=true if file change detection errored (distinct from finding no changes).
204→func collectFileChanges(ctx context.Context, ag agent.Agent, transcriptPath, repoRoot string) (modified, added, deleted []string, detectionFailed bool) {
205→	logCtx := logging.WithComponent(ctx, "attach")
206→	var transcriptFiles []string
207→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
208→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
209→			logging.Warn(logCtx, "failed to extract modified files from transcript", "error", fileErr)
210→			detectionFailed = true
211→		} else {
212→			transcriptFiles = files
213→		}
214→	}
215→
216→	changes, err := DetectFileChanges(ctx, nil)
217→	if err != nil {
218→		logging.Warn(logCtx, "failed to detect file changes, checkpoint may be incomplete", "error", err)
219→		detectionFailed = true
220→	}
221→
222→	modified = FilterAndNormalizePaths(transcriptFiles, repoRoot)
223→	if changes != nil {
224→		added = FilterAndNormalizePaths(changes.New, repoRoot)
225→		deleted = FilterAndNormalizePaths(changes.Deleted, repoRoot)
226→		modified = mergeUnique(modified, FilterAndNormalizePaths(changes.Modified, repoRoot))
227→	}
228→
229→	modified = filterToUncommittedFiles(ctx, modified, repoRoot)
230→	return modified, added, deleted, detectionFailed
231→}
