  9→func TestAppendCheckpointTrailer(t *testing.T) {
 10→	t.Parallel()
 11→
 12→	tests := []struct {
 13→		name string
 14→		msg  string
 15→		want string
 16→	}{
 17→		{
 18→			name: "no existing trailers",
 19→			msg:  "feat: add attach command\n",
 20→			want: "feat: add attach command\n\nEntire-Checkpoint: abc123def456\n",
 21→		},
 22→		{
 23→			name: "existing non-checkpoint trailer block",
 24→			msg:  "feat: add attach command\n\nSigned-off-by: Test User <test@example.com>\n",
 25→			want: "feat: add attach command\n\nSigned-off-by: Test User <test@example.com>\nEntire-Checkpoint: abc123def456\n",
 26→		},
 27→		{
 28→			name: "existing checkpoint trailer block",
 29→			msg:  "feat: add attach command\n\nEntire-Checkpoint: deadbeefcafe\n",
 30→			want: "feat: add attach command\n\nEntire-Checkpoint: deadbeefcafe\nEntire-Checkpoint: abc123def456\n",
 31→		},
 32→		{
 33→			name: "subject with colon is not trailer block",
 34→			msg:  "docs: update readme\n",
 35→			want: "docs: update readme\n\nEntire-Checkpoint: abc123def456\n",
 36→		},
 37→		{
 38→			name: "body text containing colon-space is not trailer block",
 39→			msg:  "fix: login\n\nThis fixes the error: connection refused\n",
 40→			want: "fix: login\n\nThis fixes the error: connection refused\n\nEntire-Checkpoint: abc123def456\n",
 41→		},
 42→	}
 43→
 44→	for _, tt := range tests {
 45→		t.Run(tt.name, func(t *testing.T) {
 46→			t.Parallel()
 47→			got := AppendCheckpointTrailer(tt.msg, "abc123def456")
 48→			if got != tt.want {
 49→				t.Errorf("AppendCheckpointTrailer() = %q, want %q", got, tt.want)
 50→			}
 51→		})
 52→	}
 53→}
