  9→func TestNormalizeTranscript(t *testing.T) {
 10→	t.Parallel()
 11→
 12→	// Raw Gemini format has content as array of objects for user messages,
 13→	// plus extra fields (timestamp, model, tokens) that must be preserved.
 14→	raw := []byte(`{"sessionId":"abc","messages":[{"id":"m1","type":"user","timestamp":"2026-01-01T10:00:00Z","content":[{"text":"fix the bug"}]},{"id":"m2","type":"gemini","content":"ok","model":"gemini-3-flash","tokens":{"input":100}}]}`)
 15→	normalized, err := NormalizeTranscript(raw)
 16→	if err != nil {
 17→		t.Fatalf("NormalizeTranscript() error: %v", err)
 18→	}
 19→
 20→	// After normalization, content should be a plain string
 21→	var result struct {
 22→		SessionID string `json:"sessionId"`
 23→		Messages  []struct {
 24→			ID        string `json:"id"`
 25→			Type      string `json:"type"`
 26→			Content   string `json:"content"`
 27→			Timestamp string `json:"timestamp"`
 28→			Model     string `json:"model"`
 29→		} `json:"messages"`
 30→	}
 31→	if err := json.Unmarshal(normalized, &result); err != nil {
 32→		t.Fatalf("failed to parse normalized transcript: %v", err)
 33→	}
 34→	if result.SessionID != "abc" {
 35→		t.Errorf("sessionId = %q, want %q", result.SessionID, "abc")
 36→	}
 37→	if len(result.Messages) != 2 {
 38→		t.Fatalf("expected 2 messages, got %d", len(result.Messages))
 39→	}
 40→	if result.Messages[0].Content != "fix the bug" {
 41→		t.Errorf("user content = %q, want %q", result.Messages[0].Content, "fix the bug")
 42→	}
 43→	if result.Messages[0].Timestamp != "2026-01-01T10:00:00Z" {
 44→		t.Errorf("user timestamp = %q, want preserved", result.Messages[0].Timestamp)
 45→	}
 46→	if result.Messages[1].Content != "ok" {
 47→		t.Errorf("gemini content = %q, want %q", result.Messages[1].Content, "ok")
 48→	}
 49→	if result.Messages[1].Model != "gemini-3-flash" {
 50→		t.Errorf("model = %q, want preserved", result.Messages[1].Model)
 51→	}
 52→}
