150→// writeTranscript writes transcript lines to a file in JSONL format.
151→func writeTranscript(path string, lines []transcriptLine) error {
152→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
153→	if err != nil {
154→		return fmt.Errorf("failed to create file: %w", err)
155→	}
156→	defer func() { _ = file.Close() }()
157→
158→	for _, line := range lines {
159→		data, err := json.Marshal(line)
160→		if err != nil {
161→			return fmt.Errorf("failed to marshal line: %w", err)
162→		}
163→		if _, err := file.Write(data); err != nil {
164→			return fmt.Errorf("failed to write line: %w", err)
165→		}
166→		if _, err := file.WriteString("\n"); err != nil {
167→			return fmt.Errorf("failed to write newline: %w", err)
168→		}
169→	}
170→
171→	return nil
172→}
