// runAttachExisting handles the case where a session is already tracked but may need
// condensation or commit linking. If it already has a checkpoint ID, skips straight to
// the amend prompt. Otherwise creates a transcript-only checkpoint and condenses.
func runAttachExisting(ctx context.Context, w io.Writer, state *session.State, agentName types.AgentName, force bool) error {
	sessionID := state.SessionID

	// Already has a checkpoint — just offer to link it.
	if !state.LastCheckpointID.IsEmpty() {
		checkpointIDStr := state.LastCheckpointID.String()
		fmt.Fprintf(w, "Session %s already has checkpoint %s\n", sessionID, checkpointIDStr)
		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
			logging.Warn(ctx, "failed to amend commit", "error", err)
			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
		}
		return nil
	}

	// No checkpoint yet — create a transcript-only checkpoint.
	ag, err := resolveAgentForState(state, agentName)
	if err != nil {
		return err
	}

	transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
	if err != nil {
		return fmt.Errorf("transcript not found for session %s: %w", sessionID, err)
	}

	transcriptData, err := ag.ReadTranscript(transcriptPath)
	if err != nil {
		return fmt.Errorf("failed to read transcript: %w", err)
	}

	if err := strategy.EnsureSetup(ctx); err != nil {
		return fmt.Errorf("failed to set up strategy: %w", err)
	}

	logFile, sessionDir, sessionDirAbs, err := storeTranscript(ctx, sessionID, ag.Type(), transcriptData)
	if err != nil {
		return err
	}

	author, err := GetGitAuthor(ctx)
	if err != nil {
		return fmt.Errorf("failed to get git author: %w", err)
	}

	meta := extractTranscriptMetadata(transcriptData)
	if meta.FirstPrompt != "" {
		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
		if err := os.WriteFile(promptFile, []byte(meta.FirstPrompt), 0o600); err != nil {
			logging.Warn(ctx, "failed to write prompt file", "error", err)
		}
	}

	// Update session state to point at current HEAD so the shadow branch gets
	// created at the right commit.
	repo, err := openRepository(ctx)
	if err != nil {
		return err
	}
	headRef, err := repo.Head()
	if err != nil {
		return fmt.Errorf("failed to get HEAD: %w", err)
	}
	state.BaseCommit = headRef.Hash().String()
	state.StepCount = 0
	state.Phase = session.PhaseActive
	state.TranscriptPath = logFile
	if err := strategy.SaveSessionState(ctx, state); err != nil {
		return fmt.Errorf("failed to update session state: %w", err)
	}

	if err := enrichSessionState(ctx, sessionID, ag, transcriptData, logFile, meta); err != nil {
		return err
	}

	commitMessage := generateCommitMessage(meta.FirstPrompt, ag.Type())
	stepCtx := strategy.StepContext{
		SessionID:      sessionID,
		MetadataDir:    sessionDir,
		MetadataDirAbs: sessionDirAbs,
		CommitMessage:  commitMessage,
		TranscriptPath: logFile,
		AuthorName:     author.Name,
		AuthorEmail:    author.Email,
		AgentType:      ag.Type(),
	}

	strat := GetStrategy(ctx)
	if err := strat.SaveStep(ctx, stepCtx); err != nil {
		return fmt.Errorf("failed to save checkpoint: %w", err)
	}

	checkpointIDStr, condenseErr := condenseAndFinalizeSession(ctx, strat, sessionID)

	fmt.Fprintf(w, "Attached session %s\n", sessionID)
	if condenseErr != nil {
		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
	} else {
		fmt.Fprintln(w, "  Checkpoint saved (transcript only)")
	}

	if checkpointIDStr != "" {
		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
			logging.Warn(ctx, "failed to amend commit", "error", err)
			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
		}
	}

	return nil
}

// resolveAgentForState resolves the agent from session state's AgentType,
// falling back to the --agent flag if the state has no type.
func resolveAgentForState(state *session.State, agentName types.AgentName) (agent.Agent, error) {
	// Try to find agent matching the state's AgentType
	if state.AgentType != "" {
		for _, name := range agent.List() {
			ag, err := agent.Get(name)
			if err != nil {
				continue
			}
			if ag.Type() == state.AgentType {
				return ag, nil
			}
		}
	}
	// Fall back to the --agent flag
	ag, err := agent.Get(agentName)
	if err != nil {
		return nil, fmt.Errorf("agent %q not available: %w", agentName, err)
	}
	return ag, nil
}

