 60→func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
 61→	logCtx := logging.WithComponent(ctx, "attach")
 62→
 63→	repoRoot, existingState, err := validateAttachPreconditions(ctx, sessionID)
 64→	if err != nil {
 65→		return err
 66→	}
 67→
 68→	// Fast path: session already tracked — condense if needed and offer to amend.
 69→	if existingState != nil {
 70→		return runAttachExisting(logCtx, w, existingState, agentName, force)
 71→	}
 72→
 73→	ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName)
 74→	if err != nil {
 75→		return err
 76→	}
 77→	agentType := ag.Type()
 78→
 79→	transcriptData, err := ag.ReadTranscript(transcriptPath)
 80→	if err != nil {
 81→		return fmt.Errorf("failed to read transcript: %w", err)
 82→	}
 83→
 84→	relModifiedFiles, relNewFiles, relDeletedFiles, fileDetectionFailed := collectFileChanges(ctx, ag, transcriptPath, repoRoot)
 85→
 86→	if err := strategy.EnsureSetup(ctx); err != nil {
 87→		return fmt.Errorf("failed to set up strategy: %w", err)
 88→	}
 89→
 90→	logFile, sessionDir, sessionDirAbs, err := storeTranscript(ctx, sessionID, agentType, transcriptData)
 91→	if err != nil {
 92→		return err
 93→	}
 94→
 95→	author, err := GetGitAuthor(ctx)
 96→	if err != nil {
 97→		return fmt.Errorf("failed to get git author: %w", err)
 98→	}
 99→
100→	meta := extractTranscriptMetadata(transcriptData)
101→	firstPrompt := meta.FirstPrompt
102→	commitMessage := generateCommitMessage(firstPrompt, agentType)
103→
104→	if firstPrompt != "" {
105→		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
106→		if err := os.WriteFile(promptFile, []byte(firstPrompt), 0o600); err != nil {
107→			logging.Warn(logCtx, "failed to write prompt file", "error", err)
108→		}
109→	}
110→
111→	strat := GetStrategy(ctx)
112→	if err := strat.InitializeSession(ctx, sessionID, agentType, logFile, firstPrompt, ""); err != nil {
113→		return fmt.Errorf("failed to initialize session: %w", err)
114→	}
115→
116→	if err := enrichSessionState(logCtx, sessionID, ag, transcriptData, logFile, meta); err != nil {
117→		return err
118→	}
119→
120→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
121→	stepCtx := strategy.StepContext{
122→		SessionID:      sessionID,
123→		ModifiedFiles:  relModifiedFiles,
124→		NewFiles:       relNewFiles,
125→		DeletedFiles:   relDeletedFiles,
126→		MetadataDir:    sessionDir,
127→		MetadataDirAbs: sessionDirAbs,
128→		CommitMessage:  commitMessage,
129→		TranscriptPath: logFile,
130→		AuthorName:     author.Name,
131→		AuthorEmail:    author.Email,
132→		AgentType:      agentType,
133→	}
134→
135→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
136→		return fmt.Errorf("failed to save checkpoint: %w", err)
137→	}
138→
139→	checkpointIDStr, condenseErr := condenseAndFinalizeSession(logCtx, strat, sessionID)
140→
141→	printAttachConfirmation(w, sessionID, totalChanges, fileDetectionFailed, condenseErr)
142→
143→	if checkpointIDStr != "" {
144→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
145→			logging.Warn(logCtx, "failed to amend commit", "error", err)
146→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
147→		}
148→	}
149→
150→	return nil
151→}
