153→// runAttachExisting handles the case where a session is already tracked but may need
154→// condensation or commit linking. If it already has a checkpoint ID, skips straight to
155→// the amend prompt. Otherwise creates a transcript-only checkpoint and condenses.
156→func runAttachExisting(ctx context.Context, w io.Writer, state *session.State, agentName types.AgentName, force bool) error {
157→	sessionID := state.SessionID
158→
159→	// Already has a checkpoint — just offer to link it.
160→	if !state.LastCheckpointID.IsEmpty() {
161→		checkpointIDStr := state.LastCheckpointID.String()
162→		fmt.Fprintf(w, "Session %s already has checkpoint %s\n", sessionID, checkpointIDStr)
163→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
164→			logging.Warn(ctx, "failed to amend commit", "error", err)
165→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
166→		}
167→		return nil
168→	}
169→
170→	// No checkpoint yet — create a transcript-only checkpoint.
171→	ag, err := resolveAgentForState(state, agentName)
172→	if err != nil {
173→		return err
174→	}
175→
176→	transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
177→	if err != nil {
178→		return fmt.Errorf("transcript not found for session %s: %w", sessionID, err)
179→	}
180→
181→	transcriptData, err := ag.ReadTranscript(transcriptPath)
182→	if err != nil {
183→		return fmt.Errorf("failed to read transcript: %w", err)
184→	}
185→
186→	if err := strategy.EnsureSetup(ctx); err != nil {
187→		return fmt.Errorf("failed to set up strategy: %w", err)
188→	}
189→
190→	logFile, sessionDir, sessionDirAbs, err := storeTranscript(ctx, sessionID, ag.Type(), transcriptData)
191→	if err != nil {
192→		return err
193→	}
194→
195→	author, err := GetGitAuthor(ctx)
196→	if err != nil {
197→		return fmt.Errorf("failed to get git author: %w", err)
198→	}
199→
200→	meta := extractTranscriptMetadata(transcriptData)
201→	if meta.FirstPrompt != "" {
202→		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
203→		if err := os.WriteFile(promptFile, []byte(meta.FirstPrompt), 0o600); err != nil {
204→			logging.Warn(ctx, "failed to write prompt file", "error", err)
205→		}
206→	}
207→
208→	// Update session state to point at current HEAD so the shadow branch gets
209→	// created at the right commit.
210→	repo, err := openRepository(ctx)
211→	if err != nil {
212→		return err
213→	}
214→	headRef, err := repo.Head()
215→	if err != nil {
216→		return fmt.Errorf("failed to get HEAD: %w", err)
217→	}
218→	state.BaseCommit = headRef.Hash().String()
219→	state.StepCount = 0
220→	state.Phase = session.PhaseActive
221→	state.TranscriptPath = logFile
222→	if err := strategy.SaveSessionState(ctx, state); err != nil {
223→		return fmt.Errorf("failed to update session state: %w", err)
224→	}
225→
226→	if err := enrichSessionState(ctx, sessionID, ag, transcriptData, logFile, meta); err != nil {
227→		return err
228→	}
229→
230→	commitMessage := generateCommitMessage(meta.FirstPrompt, ag.Type())
231→	stepCtx := strategy.StepContext{
232→		SessionID:      sessionID,
233→		MetadataDir:    sessionDir,
234→		MetadataDirAbs: sessionDirAbs,
235→		CommitMessage:  commitMessage,
236→		TranscriptPath: logFile,
237→		AuthorName:     author.Name,
238→		AuthorEmail:    author.Email,
239→		AgentType:      ag.Type(),
240→	}
241→
242→	strat := GetStrategy(ctx)
243→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
244→		return fmt.Errorf("failed to save checkpoint: %w", err)
245→	}
246→
247→	checkpointIDStr, condenseErr := condenseAndFinalizeSession(ctx, strat, sessionID)
248→
249→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
250→	if condenseErr != nil {
251→		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
252→	} else {
253→		fmt.Fprintln(w, "  Checkpoint saved (transcript only)")
254→	}
255→
256→	if checkpointIDStr != "" {
257→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
258→			logging.Warn(ctx, "failed to amend commit", "error", err)
259→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
260→		}
261→	}
262→
263→	return nil
264→}
