266→// resolveAgentForState resolves the agent from session state's AgentType,
267→// falling back to the --agent flag if the state has no type.
268→func resolveAgentForState(state *session.State, agentName types.AgentName) (agent.Agent, error) {
269→	// Try to find agent matching the state's AgentType
270→	if state.AgentType != "" {
271→		for _, name := range agent.List() {
272→			ag, err := agent.Get(name)
273→			if err != nil {
274→				continue
275→			}
276→			if ag.Type() == state.AgentType {
277→				return ag, nil
278→			}
279→		}
280→	}
281→	// Fall back to the --agent flag
282→	ag, err := agent.Get(agentName)
283→	if err != nil {
284→		return nil, fmt.Errorf("agent %q not available: %w", agentName, err)
285→	}
286→	return ag, nil
287→}
