289→// validateAttachPreconditions checks session ID format and git repo state.
290→// Returns the existing session state if the session is already tracked (nil if new).
291→func validateAttachPreconditions(ctx context.Context, sessionID string) (string, *session.State, error) {
292→	if err := validation.ValidateSessionID(sessionID); err != nil {
293→		return "", nil, fmt.Errorf("invalid session ID: %w", err)
294→	}
295→
296→	repoRoot, err := paths.WorktreeRoot(ctx)
297→	if err != nil {
298→		return "", nil, fmt.Errorf("not a git repository: %w", err)
299→	}
300→
301→	repo, repoErr := strategy.OpenRepository(ctx)
302→	if repoErr != nil {
303→		return "", nil, fmt.Errorf("failed to open repository: %w", repoErr)
304→	}
305→	if strategy.IsEmptyRepository(repo) {
306→		return "", nil, errors.New("repository has no commits yet — make an initial commit before running attach")
307→	}
308→
309→	store, err := session.NewStateStore(ctx)
310→	if err != nil {
311→		return "", nil, fmt.Errorf("failed to open session store: %w", err)
312→	}
313→	existing, err := store.Load(ctx, sessionID)
314→	if err != nil {
315→		return "", nil, fmt.Errorf("failed to check existing session: %w", err)
316→	}
317→
318→	return repoRoot, existing, nil
319→}
