321→// resolveAgentAndTranscript resolves the agent and transcript path, with auto-detection fallback.
322→func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName) (agent.Agent, string, error) {
323→	ag, err := agent.Get(agentName)
324→	if err != nil {
325→		return nil, "", fmt.Errorf("agent %q not available: %w", agentName, err)
326→	}
327→
328→	transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
329→	if err != nil {
330→		detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
331→		if detectErr != nil {
332→			return nil, "", fmt.Errorf("%w (also tried auto-detecting other agents: %w)", err, detectErr)
333→		}
334→		ag = detectedAg
335→		transcriptPath = detectedPath
336→		logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
337→		fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
338→	}
339→
340→	return ag, transcriptPath, nil
341→}
