343→// collectFileChanges gathers modified, new, and deleted files from both transcript analysis and git status.
344→// Returns detectionFailed=true if file change detection errored (distinct from finding no changes).
345→func collectFileChanges(ctx context.Context, ag agent.Agent, transcriptPath, repoRoot string) (modified, added, deleted []string, detectionFailed bool) {
346→	logCtx := logging.WithComponent(ctx, "attach")
347→	var transcriptFiles []string
348→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
349→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
350→			logging.Warn(logCtx, "failed to extract modified files from transcript", "error", fileErr)
351→			detectionFailed = true
352→		} else {
353→			transcriptFiles = files
354→		}
355→	}
356→
357→	changes, err := DetectFileChanges(ctx, nil)
358→	if err != nil {
359→		logging.Warn(logCtx, "failed to detect file changes, checkpoint may be incomplete", "error", err)
360→		detectionFailed = true
361→	}
362→
363→	modified = FilterAndNormalizePaths(transcriptFiles, repoRoot)
364→	if changes != nil {
365→		added = FilterAndNormalizePaths(changes.New, repoRoot)
366→		deleted = FilterAndNormalizePaths(changes.Deleted, repoRoot)
367→		modified = mergeUnique(modified, FilterAndNormalizePaths(changes.Modified, repoRoot))
368→	}
369→
370→	modified = filterToUncommittedFiles(ctx, modified, repoRoot)
371→	return modified, added, deleted, detectionFailed
372→}
