381→	}
382→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
383→		return "", "", "", fmt.Errorf("failed to create session directory: %w", err)
384→	}
385→
386→	storedTranscript := transcriptData
387→	if agentType == agent.AgentTypeGemini {
388→		if normalized, normErr := geminicli.NormalizeTranscript(transcriptData); normErr == nil {
389→			storedTranscript = normalized
390→		} else {
391→			logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
392→		}
393→	}
394→
395→	logFile = filepath.Join(sessionDirAbs, paths.TranscriptFileName)
396→	if err := os.WriteFile(logFile, storedTranscript, 0o600); err != nil {
397→		return "", "", "", fmt.Errorf("failed to write transcript: %w", err)
398→	}
399→	return logFile, sessionDir, sessionDirAbs, nil
400→}
401→
402→// printAttachConfirmation prints the post-attach status message.
403→func printAttachConfirmation(w io.Writer, sessionID string, totalChanges int, fileDetectionFailed bool, condenseErr error) {
404→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
405→	switch {
406→	case totalChanges > 0:
407→		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
408→	case fileDetectionFailed:
409→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, file change detection failed)")
410→	default:
411→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
412→	}
413→	if condenseErr != nil {
414→		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
415→	}
416→	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
417→}
418→
419→// enrichSessionState loads the session state after initialization and populates it with
420→// transcript-derived metadata (token usage, turn count, model name, duration).
421→// The meta parameter provides pre-extracted prompt/turn/model data to avoid re-parsing.
422→func enrichSessionState(ctx context.Context, sessionID string, ag agent.Agent, transcriptData []byte, transcriptPath string, meta transcriptMetadata) error {
423→	state, err := strategy.LoadSessionState(ctx, sessionID)
424→	if err != nil {
425→		return fmt.Errorf("failed to load session state: %w", err)
426→	}
427→	if state == nil {
428→		return fmt.Errorf("session state not found after initialization (session_id=%s)", sessionID)
429→	}
430→	state.CLIVersion = versioninfo.Version
431→	state.TranscriptPath = transcriptPath
432→
433→	if usage := agent.CalculateTokenUsage(ctx, ag, transcriptData, 0, ""); usage != nil {
434→		state.TokenUsage = usage
435→	}
436→	if meta.TurnCount > 0 {
437→		state.SessionTurnCount = meta.TurnCount
438→	}
439→	if meta.Model != "" {
440→		state.ModelName = meta.Model
441→	}
442→	if dur := estimateSessionDuration(transcriptData); dur > 0 {
443→		state.SessionDurationMs = dur
444→	}
445→
446→	if err := strategy.SaveSessionState(ctx, state); err != nil {
447→		return fmt.Errorf("failed to save session state: %w", err)
448→	}
449→	return nil
450→}
451→
452→// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
453→// Returns the checkpoint ID string and any condensation error.
454→// Note: accepts *strategy.ManualCommitStrategy directly because checkpoint storage is conceptually
455→// strategy-independent but currently lives on the strategy struct. Extracting it would require
456→// publicizing several private methods — worth doing if a second strategy ever appears.
457→func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
458→	var checkpointIDStr string
459→	var condenseErr error
460→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
461→		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
462→		condenseErr = err
463→	}
464→
465→	// Single load serves both checkpoint ID extraction and finalization
466→	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
467→	if loadErr != nil {
468→		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
469→		return checkpointIDStr, condenseErr
470→	}
471→	if state == nil {
472→		return checkpointIDStr, condenseErr
473→	}
474→
475→	if condenseErr == nil {
476→		checkpointIDStr = state.LastCheckpointID.String()
477→	}
478→
479→	now := time.Now()
480→	state.LastInteractionTime = &now
481→	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
482→		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
483→	}
484→	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
485→		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
486→	}
487→
488→	return checkpointIDStr, condenseErr
489→}
490→
491→// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
492→// project directories if needed.
493→func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
494→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
495→	if err != nil {
496→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
497→	}
498→	// If agent implements TranscriptPreparer, materialize the transcript before checking disk.
499→	if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
500→		if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
501→			logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
502→		}
503→	}
504→	// Agents use cwd-derived project directories, so the transcript may be stored under
505→	// a different project directory if the session was started from a different working directory.
506→	if _, statErr := os.Stat(transcriptPath); statErr == nil {
507→		return transcriptPath, nil
508→	}
509→	found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
510→	if searchErr == nil {
511→		logging.Info(ctx, "found transcript in alternative project directory", "path", found)
512→		return found, nil
513→	}
514→	logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
515→	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
516→}
517→
518→// detectAgentByTranscript tries all registered agents (except skip) to find one whose
519→// transcript resolution succeeds for the given session ID.
520→func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
521→	for _, name := range agent.List() {
522→		if name == skip {
523→			continue
524→		}
525→		ag, err := agent.Get(name)
526→		if err != nil {
527→			continue
528→		}
529→		path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
530→		if resolveErr != nil {
531→			logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
532→			continue
533→		}
534→		return ag, path, nil
535→	}
536→	return nil, "", errors.New("transcript not found for any registered agent")
537→}
