539→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
540→// When force is true, it amends without prompting.
541→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
542→	// Get HEAD commit info
543→	repo, err := openRepository(ctx)
544→	if err != nil {
545→		return fmt.Errorf("failed to open repository: %w", err)
546→	}
547→	headRef, err := repo.Head()
548→	if err != nil {
549→		return fmt.Errorf("failed to get HEAD: %w", err)
550→	}
551→	headCommit, err := repo.CommitObject(headRef.Hash())
552→	if err != nil {
553→		return fmt.Errorf("failed to get HEAD commit: %w", err)
554→	}
555→
556→	shortHash := headRef.Hash().String()[:7]
557→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
558→
559→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
560→
561→	amend := true
562→	if !force {
563→		form := NewAccessibleForm(
564→			huh.NewGroup(
565→				huh.NewConfirm().
566→					Title("Amend the last commit in this branch?").
567→					Affirmative("Y").
568→					Negative("n").
569→					Value(&amend),
570→			),
571→		)
572→		if err := form.Run(); err != nil {
573→			return fmt.Errorf("prompt failed: %w", err)
574→		}
575→	}
576→
577→	if !amend {
578→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
579→		return nil
580→	}
581→
582→	// Skip amending if this exact checkpoint ID is already in the commit
583→	for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
584→		if existing.String() == checkpointIDStr {
585→			fmt.Fprintf(w, "Commit already has Entire-Checkpoint: %s (skipping amend)\n", checkpointIDStr)
586→			return nil
587→		}
588→	}
589→
590→	// Amend the commit with the checkpoint trailer.
591→	newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
592→
593→	// --only ensures this amend updates the commit message only and does not
594→	// accidentally include unrelated staged changes.
595→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
596→	if output, err := cmd.CombinedOutput(); err != nil {
597→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
598→	}
